    const live = renderMatchUp({
      matchUp: {
        ...matchUp,
        winningSide: undefined,
        matchUpStatus: 'IN_PROGRESS'
      },
      composition: composition({})
    });
    expect(live.dataset.matchupStatus).toBe('IN_PROGRESS');
