  const {
    series
  } = buildPressureSeries({
    matchUps: fixture.matchUps
  });
  const wrapper = panel('Unrated field — refuses rather than guesses', 'A seeded draw with no ratings still produces no chart. A fabricated default would look identical to a real measurement, which is worse than nothing.');
  buildPressureChart(wrapper, series[0]);
  buildPathDifficultyBar(wrapper, series);
  return wrapper;
