  const fixture = seededDraw({
    drawSize: 32,
    seedsCount: 8
  });
  const {
    series,
    scaleName
  } = buildPressureSeries({
    matchUps: fixture.matchUps
  });
  const wrapper = panel('A whole 32-draw, in draw order', 'One 16px row per entrant, stacked in draw order so the sheet reads top to bottom. Red walls rise from the ' + 'baseline (projected to play up), blue walls hang from the top (projected to play down); deeper and darker ' + 'means a bigger rating gap. The seeded slots are the pale rows that darken toward the final — which is what ' + 'seeding is for.');
